mapper.update:
UPDATE user_reward
SET status       = 'GRANTED',
    needs_review = 0,
    claimed_at   = NULL,
    resolved_at  = NULL,
    resolved_by  = NULL
WHERE reward_policy_id = #{rewardPolicyId}
  AND status = 'REVOKED'


        AND stamp_id = #{stampId}


        AND pilgrimage_id = #{pilgrimageId}

UPDATE user_reward ur
    JOIN reward_policy rp ON rp.reward_policy_id = ur.reward_policy_id
SET ur.status = 'REVOKED'
WHERE ur.user_id = #{userId}
  AND rp.trigger_type = #{triggerType}
  AND ur.status = 'GRANTED'

UPDATE user_reward ur
    JOIN reward_policy rp ON rp.reward_policy_id = ur.reward_policy_id
SET ur.needs_review = 1
WHERE ur.user_id = #{userId}
  AND rp.trigger_type = #{triggerType}
  AND ur.status IN ('CLAIMED', 'UNDER_REVIEW', 'PAID')
